		core_rdy = 0;
		mem_inst_out_val = 0;
		exe_inst_out_val = 0;
		if (rst_n)
			case (opcode)
				7'd0, 7'd1, 7'd2, 7'd3, 7'd4, 7'd5: begin
					core_rdy = mem_rdy;
					mem_inst_out_val = inst_in_val && mem_rdy;
				end
				7'd32, 7'd33, 7'd34, 7'd35: begin
					core_rdy = exe_rdy;
					exe_inst_out_val = inst_in_val && exe_rdy;
				end
				7'd124: core_rdy = exe_rdy;
				7'd125: core_rdy = mem_rdy;
				7'd126: core_rdy = 1;
				default: core_rdy = 1;
			endcase
	end
endmodule
module mem_ctrl (
