module act (
	clk,
	rst_n,
	vpu_res_in,
	act_op_in,
	vpu_res_in_val,
	act_res_out,
	act_res_out_val
);
	input clk;
	input rst_n;
	input [15:0] vpu_res_in;
	input [2:0] act_op_in;
	input vpu_res_in_val;
	output reg [15:0] act_res_out;
	output reg act_res_out_val;
	localparam [7:0] FP8_ZERO = 8'h00;
	localparam [7:0] FP8_QNAN = 8'h7f;
	function automatic fp8_is_nan;
		input reg [6:0] magnitude;
		fp8_is_nan = magnitude == 7'h7f;
	endfunction
	function automatic [7:0] fp8_jam8;
		input reg [7:0] x;
		input reg [4:0] n;
		case (n)
			0: fp8_jam8 = x;
			1: fp8_jam8 = {1'b0, x[7:2], x[1] | x[0]};
			2: fp8_jam8 = {2'b00, x[7:3], |x[2:0]};
			3: fp8_jam8 = {3'b000, x[7:4], |x[3:0]};
			4: fp8_jam8 = {4'b0000, x[7:5], |x[4:0]};
			5: fp8_jam8 = {5'b00000, x[7:6], |x[5:0]};
			6: fp8_jam8 = {6'b000000, x[7], |x[6:0]};
			default: fp8_jam8 = {7'b0000000, |x};
		endcase
	endfunction
	function automatic [4:0] sv2v_cast_5;
		input reg [4:0] inp;
		sv2v_cast_5 = inp;
	endfunction
	function automatic [7:0] fp8_add;
		input reg [7:0] a;
		input reg [7:0] b;
		reg [7:0] hi_operand;
		reg [7:0] lo_operand;
		reg [4:0] el;
		reg [4:0] es;
		reg [4:0] exponent;
		reg [4:0] rounded;
		reg [3:0] ml;
		reg [3:0] ms;
		reg [7:0] aligned;
		reg [7:0] total;
		reg [0:1] _sv2v_jump;
		begin
			_sv2v_jump = 2'b00;
			if (fp8_is_nan(a[6:0]) || fp8_is_nan(b[6:0])) begin
				fp8_add = FP8_QNAN;
				_sv2v_jump = 2'b11;
			end
			if (_sv2v_jump == 2'b00) begin
				hi_operand = (a[6:0] >= b[6:0] ? a : b);
				lo_operand = (a[6:0] >= b[6:0] ? b : a);
				el = (hi_operand[6:3] == 0 ? 5'd1 : {1'b0, hi_operand[6:3]});
				es = (lo_operand[6:3] == 0 ? 5'd1 : {1'b0, lo_operand[6:3]});
				ml = {hi_operand[6:3] != 0, hi_operand[2:0]};
				ms = {lo_operand[6:3] != 0, lo_operand[2:0]};
				aligned = fp8_jam8({1'b0, ms, 3'b000}, el - es);
				total = (hi_operand[7] == lo_operand[7] ? {1'b0, ml, 3'b000} + aligned : {1'b0, ml, 3'b000} - aligned);
				if (total == 0) begin
					fp8_add = (a[7] && b[7] ? 8'h80 : FP8_ZERO);
					_sv2v_jump = 2'b11;
				end
				if (_sv2v_jump == 2'b00) begin
					exponent = el;
					if (total[7]) begin
						total = fp8_jam8(total, 5'd1);
						exponent = exponent + 1'b1;
					end
					begin : sv2v_autoblock_1
						reg signed [31:0] i;
						for (i = 0; i < 6; i = i + 1)
							if (!total[6] && (exponent > 1)) begin
								total = total << 1;
								exponent = exponent - 1'b1;
							end
					end
					rounded = {1'b0, total[6:3]} + sv2v_cast_5(total[2] && ((total[1] || total[0]) || total[3]));
					if (rounded[4]) begin
						rounded = rounded >> 1;
						exponent = exponent + 1'b1;
					end
					if ((exponent > 15) || ((exponent == 15) && (rounded > 14))) begin
						fp8_add = {hi_operand[7], 7'h7e};
						_sv2v_jump = 2'b11;
					end
					if (_sv2v_jump == 2'b00) begin
						if ((exponent == 1) && (rounded < 8)) begin
							fp8_add = {hi_operand[7], 4'b0000, rounded[2:0]};
							_sv2v_jump = 2'b11;
						end
						if (_sv2v_jump == 2'b00) begin
							fp8_add = {hi_operand[7], exponent[3:0], rounded[2:0]};
							_sv2v_jump = 2'b11;
						end
					end
				end
			end
		end
	endfunction
	function automatic signed [4:0] sv2v_cast_5_signed;
		input reg signed [4:0] inp;
		sv2v_cast_5_signed = inp;
	endfunction
	function automatic signed [6:0] sv2v_cast_7_signed;
		input reg signed [6:0] inp;
		sv2v_cast_7_signed = inp;
	endfunction
	function automatic [8:0] sv2v_cast_9;
		input reg [8:0] inp;
		sv2v_cast_9 = inp;
	endfunction
	function automatic signed [3:0] sv2v_cast_4_signed;
		input reg signed [3:0] inp;
		sv2v_cast_4_signed = inp;
	endfunction
	function automatic [7:0] fp8_pack8;
		input reg sign;
		input reg [7:0] magnitude;
		input reg signed [6:0] scale;
		reg signed [4:0] msb;
		reg signed [6:0] exponent;
		reg signed [6:0] shift;
		reg [8:0] truncated;
		reg [8:0] remainder;
		reg [8:0] halfway;
		reg [8:0] rounded;
		reg [3:0] encoded;
		reg [0:1] _sv2v_jump;
		begin
			_sv2v_jump = 2'b00;
			msb = -5'sd1;
			truncated = 0;
			remainder = 0;
			halfway = 0;
			rounded = 0;
			encoded = 0;
			begin : sv2v_autoblock_2
				reg signed [31:0] i;
				for (i = 0; i < 8; i = i + 1)
					if (magnitude[i])
						msb = sv2v_cast_5_signed(i);
			end
			if (msb < 0) begin
				fp8_pack8 = {sign, 7'b0000000};
				_sv2v_jump = 2'b11;
			end
			if (_sv2v_jump == 2'b00) begin
				exponent = sv2v_cast_7_signed(msb) + scale;
				if (exponent > 8) begin
					fp8_pack8 = {sign, 7'h7e};
					_sv2v_jump = 2'b11;
				end
				if (_sv2v_jump == 2'b00) begin
					shift = (exponent >= -6 ? sv2v_cast_7_signed(msb) - 7'sd3 : -(7'sd9 + scale));
					if (shift > 8)
						rounded = 0;
					else if (shift > 0) begin
						truncated = {1'b0, magnitude} >> shift;
						remainder = {1'b0, magnitude} - (truncated << shift);
						halfway = 9'd1 << (shift - 1'b1);
						rounded = truncated + sv2v_cast_9((remainder > halfway) || ((remainder == halfway) && truncated[0]));
					end
					else
						rounded = {1'b0, magnitude} << -shift;
					if (exponent < -6) begin
						if (rounded >= 8) begin
							fp8_pack8 = {sign, 7'h08};
							_sv2v_jump = 2'b11;
						end
						if (_sv2v_jump == 2'b00) begin
							fp8_pack8 = {sign, 4'b0000, rounded[2:0]};
							_sv2v_jump = 2'b11;
						end
					end
					if (_sv2v_jump == 2'b00) begin
						if (rounded >= 16) begin
							rounded = rounded >> 1;
							exponent = exponent + 1'b1;
						end
						if ((exponent > 8) || ((exponent == 8) && (rounded > 14))) begin
							fp8_pack8 = {sign, 7'h7e};
							_sv2v_jump = 2'b11;
						end
						if (_sv2v_jump == 2'b00) begin
							encoded = sv2v_cast_4_signed(exponent + 7'sd7);
							fp8_pack8 = {sign, encoded[3:0], rounded[2:0]};
							_sv2v_jump = 2'b11;
						end
					end
				end
			end
		end
	endfunction
	function automatic [7:0] fp8_mul;
		input reg [7:0] a;
		input reg [7:0] b;
		reg [3:0] ma;
		reg [3:0] mb;
		reg [7:0] product;
		reg signed [6:0] ea;
		reg signed [6:0] eb;
		reg [0:1] _sv2v_jump;
		begin
			_sv2v_jump = 2'b00;
			if (fp8_is_nan(a[6:0]) || fp8_is_nan(b[6:0])) begin
				fp8_mul = FP8_QNAN;
				_sv2v_jump = 2'b11;
			end
			if (_sv2v_jump == 2'b00) begin
				ma = {a[6:3] != 0, a[2:0]};
				mb = {b[6:3] != 0, b[2:0]};
				ea = (a[6:3] == 0 ? -7'sd9 : $signed({3'b000, a[6:3]}) - 7'sd10);
				eb = (b[6:3] == 0 ? -7'sd9 : $signed({3'b000, b[6:3]}) - 7'sd10);
				product = ma * mb;
				fp8_mul = fp8_pack8(a[7] ^ b[7], product, ea + eb);
				_sv2v_jump = 2'b11;
			end
		end
	endfunction
	function automatic [7:0] fp8_sigmoid;
		input reg [7:0] x;
		reg [3:0] mantissa;
		reg signed [6:0] scale;
		reg [0:1] _sv2v_jump;
		begin
			_sv2v_jump = 2'b00;
			if (fp8_is_nan(x[6:0])) begin
				fp8_sigmoid = FP8_QNAN;
				_sv2v_jump = 2'b11;
			end
			if (_sv2v_jump == 2'b00) begin
				if (x[6:0] >= 7'h40) begin
					fp8_sigmoid = (x[7] ? 8'h00 : 8'h38);
					_sv2v_jump = 2'b11;
				end
				if (_sv2v_jump == 2'b00) begin
					mantissa = {x[6:3] != 0, x[2:0]};
					scale = (x[6:3] == 0 ? -7'sd11 : $signed({3'b000, x[6:3]}) - 7'sd12);
					fp8_sigmoid = fp8_add(fp8_pack8(x[7], {4'b0000, mantissa}, scale), 8'h30);
					_sv2v_jump = 2'b11;
				end
			end
		end
	endfunction
	function automatic [7:0] fp8_tanh;
		input reg [7:0] x;
		reg [0:1] _sv2v_jump;
		begin
			_sv2v_jump = 2'b00;
			if (fp8_is_nan(x[6:0])) begin
				fp8_tanh = FP8_QNAN;
				_sv2v_jump = 2'b11;
			end
			if (_sv2v_jump == 2'b00) begin
				if (x[6:0] >= 7'h38) begin
					fp8_tanh = (x[7] ? 8'hb8 : 8'h38);
					_sv2v_jump = 2'b11;
				end
				if (_sv2v_jump == 2'b00) begin
					fp8_tanh = x;
					_sv2v_jump = 2'b11;
				end
			end
		end
	endfunction
	always @(posedge clk)
		if (!rst_n) begin
			act_res_out <= 0;
			act_res_out_val <= 0;
		end
		else begin
			act_res_out_val <= vpu_res_in_val;
			if (vpu_res_in_val) begin : sv2v_autoblock_3
				integer lane;
				for (lane = 0; lane < 2; lane = lane + 1)
					case (act_op_in)
						3'd0: act_res_out[lane * 8+:8] <= vpu_res_in[lane * 8+:8];
						3'd1: act_res_out[lane * 8+:8] <= (fp8_is_nan(vpu_res_in[lane * 8+:7]) ? FP8_QNAN : (vpu_res_in[((lane + 1) * 8) - 1] ? FP8_ZERO : vpu_res_in[lane * 8+:8]));
						3'd2: act_res_out[lane * 8+:8] <= fp8_sigmoid(vpu_res_in[lane * 8+:8]);
						3'd4: act_res_out[lane * 8+:8] <= (fp8_is_nan(vpu_res_in[lane * 8+:7]) ? FP8_QNAN : (!vpu_res_in[((lane + 1) * 8) - 1] && (vpu_res_in[lane * 8+:7] != 0) ? 8'h38 : FP8_ZERO));
						3'd3: act_res_out[lane * 8+:8] <= fp8_tanh(vpu_res_in[lane * 8+:8]);
						default: act_res_out[lane * 8+:8] <= vpu_res_in[lane * 8+:8];
					endcase
			end
		end
endmodule
module mem_itf (
	clk,
	rst_n,
	read_en,
	write_en,
	copy_en,
	rdy,
	src_addr,
	dst_addr,
	write_data,
	read_data,
	read_data_val,
	qspi_req_val,
	qspi_req_rdy,
	qspi_req_write,
	qspi_req_addr,
	qspi_req_data,
	qspi_read_data,
	qspi_read_data_val
);
	input clk;
	input rst_n;
	input read_en;
	input write_en;
	input copy_en;
	output reg rdy;
	input [24:0] src_addr;
	input [24:0] dst_addr;
	input [15:0] write_data;
	output reg [15:0] read_data;
	output reg read_data_val;
	output reg qspi_req_val;
	input qspi_req_rdy;
	output reg qspi_req_write;
	output reg [24:0] qspi_req_addr;
	output reg [15:0] qspi_req_data;
	input [15:0] qspi_read_data;
	input qspi_read_data_val;
	localparam [1:0] IDLE = 2'd0;
	localparam [1:0] SEND = 2'd1;
	localparam [1:0] WAIT = 2'd2;
	reg [1:0] state;
	reg copy_pending;
	reg [24:0] copy_dst_addr;
	always @(*) begin
		rdy = state == IDLE;
		qspi_req_val = rst_n && (state == SEND);
	end
	always @(posedge clk)
		if (!rst_n) begin
			state <= IDLE;
			copy_pending <= 0;
			copy_dst_addr <= 0;
			qspi_req_write <= 0;
			qspi_req_addr <= 0;
			qspi_req_data <= 0;
			read_data <= 0;
			read_data_val <= 0;
		end
		else begin
			read_data_val <= 0;
			case (state)
				IDLE:
					if ((read_en || write_en) || copy_en) begin
						qspi_req_write <= write_en;
						qspi_req_addr <= (write_en ? dst_addr : src_addr);
						qspi_req_data <= write_data;
						copy_pending <= copy_en;
						copy_dst_addr <= dst_addr;
						state <= SEND;
					end
				SEND:
					if (qspi_req_rdy)
						state <= WAIT;
				WAIT:
					if (qspi_read_data_val) begin
						if (copy_pending) begin
							qspi_req_write <= 1;
							qspi_req_addr <= copy_dst_addr;
							qspi_req_data <= qspi_read_data;
							copy_pending <= 0;
							state <= SEND;
						end
						else begin
							if (!qspi_req_write) begin
								read_data <= qspi_read_data;
								read_data_val <= 1;
							end
							state <= IDLE;
						end
					end
				default: state <= IDLE;
			endcase
		end
endmodule
module qspi_ctrl (
	clk,
	rst_n,
	req_val,
	req_rdy,
	req_write,
	req_addr,
	req_data,
	read_data,
	read_data_val,
	sck,
	flash_sc_n,
	psram_a_sc_n,
	psram_b_sc_n,
	dq_in,
	dq_out,
	dq_oe
);
	input clk;
	input rst_n;
	input req_val;
	output wire req_rdy;
	input req_write;
	input [24:0] req_addr;
	input [15:0] req_data;
	output reg [15:0] read_data;
	output reg read_data_val;
	output reg sck;
	output reg flash_sc_n;
	output reg psram_a_sc_n;
	output reg psram_b_sc_n;
	input [3:0] dq_in;
	output reg [3:0] dq_out;
	output reg [3:0] dq_oe;
	localparam [3:0] IDLE = 0;
	localparam [3:0] SELECT = 1;
	localparam [3:0] CMD = 2;
	localparam [3:0] ADDR = 3;
	localparam [3:0] DUMMY = 4;
	localparam [3:0] DATA = 5;
	localparam [3:0] STATUS = 6;
	localparam [3:0] DESELECT = 7;
	localparam [3:0] CHECK = 8;
	localparam [2:0] MEMORY = 0;
	localparam [2:0] WAIT_READY = 1;
	localparam [2:0] WRITE_ENABLE = 2;
	localparam [2:0] CHECK_ENABLE = 3;
	localparam [2:0] WAIT_PROGRAM = 4;
	reg [3:0] state;
	reg [2:0] operation;
	reg [1:0] chip;
	reg [23:0] addr_shift;
	reg write_reg;
	reg [7:0] cmd_shift;
	reg [15:0] data_shift;
	reg [1:0] status_shift;
	reg [4:0] cycles_left;
	wire is_ram = chip[1];
	wire [7:0] memory_opcode = (is_ram ? (write_reg ? 8'h02 : 8'h0b) : (write_reg ? 8'h32 : 8'h6b));
	assign req_rdy = (rst_n && (state == IDLE)) && !req_addr[0];
	always @(*) begin
		dq_out = 4'b1100;
		dq_oe = 4'b0000;
		case (state)
			CMD:
				if (is_ram) begin
					dq_out = cmd_shift[7:4];
					dq_oe = 4'b1111;
				end
				else begin
					dq_out[0] = cmd_shift[7];
					dq_oe = 4'b1101;
				end
			ADDR:
				if (is_ram) begin
					dq_out = addr_shift[23:20];
					dq_oe = 4'b1111;
				end
				else begin
					dq_out[0] = addr_shift[23];
					dq_oe = 4'b1101;
				end
			DATA:
				if (write_reg) begin
					dq_out = data_shift[15:12];
					dq_oe = 4'b1111;
				end
			STATUS: dq_oe = 4'b1101;
			default:
				;
		endcase
	end
	always @(posedge clk)
		if (!rst_n) begin
			state <= IDLE;
			operation <= MEMORY;
			chip <= 0;
			addr_shift <= 0;
			write_reg <= 0;
			cmd_shift <= 0;
			data_shift <= 0;
			status_shift <= 0;
			cycles_left <= 0;
			read_data <= 0;
			read_data_val <= 0;
			sck <= 0;
			flash_sc_n <= 1;
			psram_a_sc_n <= 1;
			psram_b_sc_n <= 1;
		end
		else begin
			read_data_val <= 0;
			case (state)
				IDLE:
					if (req_val && req_rdy) begin
						chip <= req_addr[24:23];
						addr_shift <= (req_addr[24] ? {1'b0, req_addr[22:0]} : req_addr[23:0]);
						write_reg <= req_write;
						data_shift <= {req_data[7:0], req_data[15:8]};
						operation <= (req_addr[24] ? MEMORY : WAIT_READY);
						state <= SELECT;
					end
				SELECT: begin
					flash_sc_n <= is_ram;
					psram_a_sc_n <= chip != 2'b10;
					psram_b_sc_n <= chip != 2'b11;
					sck <= 0;
					if (operation == MEMORY)
						cmd_shift <= memory_opcode;
					else
						cmd_shift <= (operation == WRITE_ENABLE ? 8'h06 : 8'h05);
					cycles_left <= (is_ram ? 1 : 7);
					state <= CMD;
				end
				CMD, ADDR, DUMMY, DATA, STATUS: begin
					sck <= !sck;
					if (!sck) begin
						if ((state == DATA) && !write_reg)
							data_shift <= {data_shift[11:0], dq_in};
						if (state == STATUS)
							status_shift <= {status_shift[0], dq_in[1]};
					end
					else if (cycles_left != 0) begin
						cycles_left <= cycles_left - 1'b1;
						case (state)
							CMD: cmd_shift <= cmd_shift << (is_ram ? 4 : 1);
							ADDR: addr_shift <= addr_shift << (is_ram ? 4 : 1);
							DATA:
								if (write_reg)
									data_shift <= {data_shift[11:0], 4'b0000};
							default:
								;
						endcase
					end
					else
						case (state)
							CMD:
								if (operation == MEMORY) begin
									cycles_left <= (is_ram ? 5 : 23);
									state <= ADDR;
								end
								else if (operation == WRITE_ENABLE)
									state <= DESELECT;
								else begin
									cycles_left <= 7;
									state <= STATUS;
								end
							ADDR:
								if (write_reg) begin
									cycles_left <= 3;
									state <= DATA;
								end
								else begin
									cycles_left <= (is_ram ? 3 : 7);
									state <= DUMMY;
								end
							DUMMY: begin
								cycles_left <= 3;
								state <= DATA;
							end
							DATA: begin
								if (!write_reg)
									read_data <= {data_shift[7:0], data_shift[15:8]};
								state <= DESELECT;
							end
							STATUS: state <= DESELECT;
							default: state <= DESELECT;
						endcase
				end
				DESELECT: begin
					flash_sc_n <= 1;
					psram_a_sc_n <= 1;
					psram_b_sc_n <= 1;
					state <= CHECK;
				end
				CHECK:
					case (operation)
						MEMORY:
							if (!is_ram && write_reg) begin
								operation <= WAIT_PROGRAM;
								state <= SELECT;
							end
							else begin
								read_data_val <= 1;
								state <= IDLE;
							end
						WAIT_READY: begin
							if (!status_shift[0])
								operation <= (write_reg ? WRITE_ENABLE : MEMORY);
							state <= SELECT;
						end
						WRITE_ENABLE: begin
							operation <= CHECK_ENABLE;
							state <= SELECT;
						end
						CHECK_ENABLE: begin
							if (!status_shift[0] && status_shift[1])
								operation <= MEMORY;
							else
								operation <= WAIT_READY;
							state <= SELECT;
						end
						WAIT_PROGRAM:
							if (status_shift[0])
								state <= SELECT;
							else begin
								read_data_val <= 1;
								state <= IDLE;
							end
						default: state <= IDLE;
					endcase
				default: begin
					state <= IDLE;
					sck <= 0;
					flash_sc_n <= 1;
					psram_a_sc_n <= 1;
					psram_b_sc_n <= 1;
				end
			endcase
		end
endmodule
